                                                                                                                                                                                                                 
  CREATE TABLE "STS_FOLDER_LIB"                                                                                                                                                                        
   (	"FOLDER_LIB_ID" NUMBER(20,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"FOLDER_CLASS_ID" NUMBER(20,0),                                                                                                                                                                                 
	"FOLDER_LIB_NAME" VARCHAR2(300),                                                                                                                                                                                
	"FOLDER_LIB_URL" VARCHAR2(255),                                                                                                                                                                                 
	"FOLDER_LIB_NAME_ORI" VARCHAR2(10),                                                                                                                                                                             
	"FOLDER_LIB_URL_ORI" VARCHAR2(2000),                                                                                                                                                                            
	"FOLDER_LIB_STATUS" VARCHAR2(10),                                                                                                                                                                               
	"FOLDER_LIB_TYPE" NUMBER(1,0),                                                                                                                                                                                  
	"FOLDER_LIB_DATE" DATE,                                                                                                                                                                                         
	"DEL_FLAG" NUMBER(1,0) DEFAULT 0,                                                                                                                                                                               
	"DEL_DATE" DATE,                                                                                                                                                                                                
	"REMARK" VARCHAR2(500),                                                                                                                                                                                         
	"SYSTEM_ID" NUMBER(20,0),                                                                                                                                                                                       
	"TENANT_ID" NUMBER(20,0),                                                                                                                                                                                       
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                                      
	"CREATION_DATE" DATE DEFAULT sysdate,                                                                                                                                                                           
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                                      
	"UPDATE_DATE" DATE DEFAULT sysdate,                                                                                                                                                                             
	"SCOPE_TYPE" NVARCHAR2(20),                                                                                                                                                                                     
	 PRIMARY KEY ("FOLDER_LIB_ID")                                                                                                                                                                                  
  USING INDEX  ENABLE                                                                                                                                                                                            
   ) ;                                                                                                                                                                                                           
